void CDynArray::Reserve(int c)
{
    if (m_cMax < c)
    {
        int cMax;
        if (c < 0x200)
        {
            cMax = m_cMax ? m_cMax : 8;
            while (cMax < c)
                cMax *= 2;
        }
        else
        {
            cMax = (c + 0x3FF) & ~0x3FF;
        }
        m_pv = m_pheap->PvRealloc(m_pv, cMax * m_cb, 4);
        m_cMax = cMax;
    }
}

